  function customerForm(c={}){return form('customer',input('name','客户公司名称',c.name,'text','','required maxlength="200"')+input('website','官方网站',c.website,'url')+input('owner','销售负责人',c.owner)+input('industry','业务领域',c.industry)+input('headquarters_country','总部国家代码',c.headquarters_country,'text','总部不代表所有经营国家，例如 NL')+check('headquarters_country_confirmed','总部国家已依据来源核实',c.headquarters_country_confirmed)+input('operating_countries','经营国家代码（可多选）',arr(c.operating_countries).join(', '),'text','例如 NL, US, GB；与人员工作所在地、商品市场分开记录')+check('operating_countries_confirmed','上述经营国家已依据来源核实',c.operating_countries_confirmed)+input('linkedin_search_countries','领英检索国家（可多选）',arr(c.linkedin_search_countries ?? c.operating_countries).join(', '),'text','例如 AU, GB；保存后自动应用 Locations')+input('group_company','所属集团',c.group_company)+select('parent_customer_id','母公司客户档案',[['','未关联母公司'],...S.customers.filter(item=>item.id!==c.id).map(item=>[item.id,item.name])],c.parent_customer_id)+area('focus','客户重点与身份确认依据',c.focus)+check('followed','加入领导关注客户',c.followed),c.id?'保存客户信息':'建立客户档案');}
