  const observationTerm=(field,value)=>field==='product_level'?(value==='family'?'产品系列（非具体型号）':val(value)):field==='tax_basis'?({included:'含税',excluded:'未税',unknown:'未确认'}[value]||val(value)):field==='shipping_basis'?({included:'已含运费',excluded:'运费另计',unknown:'未确认'}[value]||val(value)):val(value);
  function observationsView(){return focusView('products')+panel('产品与人员观测',note('价格、评论数、销量仅记录来源实际公开值。空白保留未知。价格仅在币种、计量单位、包装和明确税费条件一致时比较；若记录运费，口径也须一致。税费未确认不生成价格变化。')+table(['观测对象','公开数据','来源 / 时间','状态'],arr(S.detail.observations).map(o=>[esc(o.values?.name||o.values?.title||o.entity_key),esc(Object.entries(o.values||{}).filter(([k,v])=>v!==null&&v!==''&&['price','currency','unit','pack_quantity','review_count','sales_count','sales_period','sales_scope','availability','title','company','model','category','tax_basis','shipping_basis','product_level'].includes(k)).map(([k,v])=>({price:'价格',currency:'币种',unit:'单位',pack_quantity:'包装数量',review_count:'评论数',sales_count:'公开销量',sales_period:'销量期间',sales_scope:'销量范围',availability:'可售状态',title:o.kind==='person'?'职务':'标题',company:'公司',model:'型号',category:'类别',tax_basis:'税费口径',shipping_basis:'运费口径',product_level:'产品层级'}[k]+'：'+observationTerm(k,v))).join(' · ')),link(o.source_url,'查看来源')+'<br>'+esc(stamp(o.observed_at))+(arr(o.evidence).length?`<details class="bh-evidence-summary"><summary>规格与证据摘要（${arr(o.evidence).length} 条）</summary>${evidence(o.evidence)}</details>`:''),badge(o.status,o.status==='failed'?'danger':'')]))+panel('登记新的产品 / 人物观测',form('observation',select('kind','观测类型',[['product','产品'],['person','人物']])+input('entity_key','稳定标识（产品建议使用来源网址）','','text','产品用来源网址可接续自动采集；人物使用档案编号。','required')+input('name','产品 / 人物名称')+input('source_url','观测来源网址','','url','','required')+input('observed_at','观测日期与时间','','datetime-local')+select('status','本次取得结果',[['success','成功取得公开数据'],['failed','来源失败 / 无法读取']])+input('price','公开价格','','number','','min="0" step="any"')+input('currency','币种代码','','text','例如 USD、EUR、CNY')+select('tax_basis','公开价格税费条件',[['unknown','未确认（不比较价格）'],['included','含税'],['excluded','未税']],'unknown')+select('shipping_basis','公开价格运费条件（可选）',[['unknown','未确认'],['included','已含运费'],['excluded','运费另计']],'unknown')+input('unit','计价单位','','text','例如 piece、pack、kg')+input('pack_quantity','每包数量','','number','','min="1" step="1"')+input('review_count','公开评论数','','number','','min="0" step="1"')+input('sales_count','公开销量（确有公开值时）','','number','','min="0" step="1"')+input('sales_period','销量统计期间','','text','填写销量时必填，例如 2026-09 或最近 30 天')+input('sales_scope','销量统计范围','','text','填写销量时必填，例如该商品链接、美国线上店铺')+input('availability','公开可售状态')+input('title','职务（人物观测）')+input('company','任职公司（人物观测）')+input('model','产品型号')+input('category','产品类别')+evidenceFields(),'保存观测'),true)+panel('已识别变化',eventsView(arr(S.detail.events))));}
  function changeRows(event){const labels={name:'名称',category:'类别',model:'型号',price:'价格',currency:'币种',unit:'计价单位',pack_quantity:'每包数量',review_count:'评论数',sales_count:'公开销量',sales_period:'销量统计期间',sales_scope:'销量统计范围',title:'职位',company:'任职公司',department:'部门',start_date:'任职开始时间',end_date:'任职结束时间',published_at:'来源发布日期',availability:'可售状态',tax_basis:'税费口径',shipping_basis:'运费口径',product_level:'产品层级'};return Array.isArray(event.changes)?event.changes.map(v=>[labels[v.field]||'其他信息',`${observationTerm(v.field,v.before)} → ${observationTerm(v.field,v.after)}`]):Object.entries(event.changes||{}).map(([field,value])=>[labels[field]||'其他信息',value&&typeof value==='object'?`${observationTerm(field,value.before)} → ${observationTerm(field,value.after)}`:val(value)]);}
  function eventFollowup(event){return `${event.impact?note('待核实影响：'+event.impact):''}${event.followup_owner||event.followup_action?facts([['跟进负责人',event.followup_owner],['建议行动',event.followup_action]]):''}`;}
  function eventsView(events){return events.length?events.map(e=>`<article class="bh-card"><header><strong>${esc(e.title||e.summary||text(e.kind)||'已记录变化')}</strong><div>${e.importance>=3?badge('优先关注','warning'):''} ${badge(e.status||'待核验')}</div></header><p>${esc(e.description||e.message||e.summary||'')}</p>${facts(changeRows(e))}${eventFollowup(e)}<small class="bh-muted">${esc(stamp(e.observed_at||e.created_at))}</small>${link(e.source_url,'原始来源')}${arr(e.evidence).length?`<details class="bh-evidence-summary"><summary>展开来源与完整依据（${arr(e.evidence).length}）</summary>${evidence(e.evidence)}</details>`:''}</article>`).join(''):empty('尚未识别到有依据的变化；至少需要两次可比较的成功观测。');}
  function strategyItemView(strategy,item){const canEdit=has('customer_write'),frozen=item.status==='approved',departmentStatus=item.department_reviews?.[auth().user?.role]?.status;let actions='';if(frozen)actions=note('已确认，当前条目已冻结；后续调整请生成新的策略版本。');else if(has('review_write')){const fields=(canEdit?area('revised_text','修订策略条目',item.text)+input('owner','行动负责人',item.owner)+input('due_date','完成期限',item.due_date,'date'):'')+select('status','会审结论',[['pending','待会审'],['approved',has('review_confirm')?'最终通过':'部门建议通过'],['needs_evidence','待补证据'],['rejected','不通过']],departmentStatus||item.status||'pending')+select('department','会审部门',departmentChoices())+area('note','核对意见')+input('elapsed_minutes','本次会审用时（分钟）','','number','','min="0" step="1"');actions=`<form id="bh-review-${esc(item.id)}" class="bh-form" data-strategy-id="${esc(strategy.id)}" data-item-id="${esc(item.id)}"><fieldset ${busy?'disabled':''}><div class="bh-fields">${fields}</div><button class="button" type="submit">保存会审</button></fieldset></form>`;}return `<div class="bh-result-row"><p>${esc(item.text)}</p>${badge(item.status||'pending')}${facts([['行动负责人',item.owner],['完成期限',item.due_date]])}${departmentReviewView(item)} ${arr(item.reference_ids).map(id=>{const ref=arr(strategy.references).find(r=>r.id===id);return ref?link(ref.url,ref.title||'来源'):'';}).join(' ')}${actions}</div>`;}
  function strategyView(){const strategies=arr(S.detail.strategies);return panel('客户策略与跨部门核对',note('策略由客户渠道、人物、产品、工厂能力和关联研发项目共同支撑。销售与管理者可修订行动；研发和采购记录部门意见，管理者最终确认后冻结条目。')+form('strategy',check('use_ai','使用已配置大模型整理策略',false),'生成新策略草案')+strategies.map(s=>`<article class="bh-card" data-bh-strategy-id="${esc(s.id)}"><header><div><strong>${esc(customer()?.name||'客户')} · ${esc(s.title||'客户策略草案')}${s.version?' · 版本 '+esc(s.version):''}</strong> ${badge(s.status)}${s.refresh_reason?note(s.refresh_reason):''}<p class="bh-muted">${esc(stamp(s.created_at||s.generated_at))} · ${esc(s.mode||'资料与规则整理')}</p></div><div class="bh-actions"><a class="button" href="${esc(cp('export')+'?'+new URLSearchParams({strategy_id:s.id}))}" download>导出策略</a>${button('strategy-print','打印摘要',`data-id="${esc(s.id)}"`)}</div></header>${arr(s.sections).map(section=>`<section><h4>${esc(section.title)}</h4>${arr(section.items).map(item=>strategyItemView(s,item)).join('')}</section>`).join('')}${s.ai?.answer?`<h4>AI 辅助策略</h4><div class="bh-answer">${esc(s.ai.answer)}</div>`:''}${evidence(s.references)}</article>`).join('')+(strategies.length?'':empty('尚未生成客户策略。补充客户、人物、产品与工厂依据后生成。')));}
  function answerModeLabel(a){const mode=a.engine||a.mode;if(mode==='evidence_only')return a.status==='failed'?'模型失败，已回退资料检索':'资料检索';if(mode==='cloud_model')return '模型整理';return '已保存结果';}
