  function customersView(){if(S.settingsOnly||S.showAI)return ctx.heading('模型与 AI 设置','管理员集中维护模型连接；业务页面在具体任务旁调用 AI。','<a class="button" href="#access">返回账户设置</a>')+aiView();const c=customer(),tabs=[['overview','总览'],['people','关键人物'],['products','产品与市场'],['opportunities','机会与行动']];return `<a class="bh-directory-back" href="#customer-directory">← 客户列表</a>`+ctx.heading(c?.name||'建立客户档案',c?`${c.owner?'负责人：'+c.owner:'负责人待分配'} · ${c.followed?'领导关注客户':'普通客户'} · ${arr(c.operating_countries).join(' / ')||'经营国家待核实'}`:'先确认公司主体；同名公司和子公司分别建档。',c?`<button type="button" class="button button-primary" data-people-database-open data-customer-id="${esc(c.id)}">人物研究库</button><button type="button" class="button" data-org-report-open data-customer-id="${esc(c.id)}">员工框架报告</button>`+button('drawer','补充资料','data-value="source"',!has('customer_write'))+button('drawer','编辑档案','data-value="customer"',!has('customer_write'))+button('drawer','更多','data-value="settings"'):button('research-new','从公司名开始研究','',!has('customer_write')))+(S.newResearch?newResearchView():'')+(c?`<nav class="bh-tabs" role="tablist" aria-label="客户工作区">${tabs.map(([k,t])=>`<a role="tab" aria-selected="${S.tab===k}" href="#customers/${esc(c.id)}/${k}">${t}</a>`).join('')}</nav><div role="tabpanel" aria-label="${esc(tabs.find(t=>t[0]===S.tab)?.[1]||'客户总览')}">${S.tab==='people'?peopleView():S.tab==='products'?(window.LumiCustomerProductResearch?.view(c,{events:arr(S.detail.events)})||'')+'<details class="cpr-legacy-tools"><summary>手动维护产品型号与渠道商品</summary>'+(window.LumiObjects?.customerPanel('market')||'')+'</details>'+panel('原始观察与变化记录',observationsView(),true):S.tab==='opportunities'?(window.LumiObjects?.customerPanel('opportunities')||'')+panel('客户策略与历史会审',strategyView(),true):customerOverview()}</div>`:(S.newResearch?'':customerOverview()))+drawerView();}
  function filteredNews(){return (window.LumiLeadershipBoard?.rank?.(S.news,S)||S.news).filter(e=>(!S.newsCustomer||e.customer_id===S.newsCustomer)&&(!S.newsKind||(e.kind||e.entity_type)===S.newsKind)&&(!S.newsCountry||(window.LumiLeadershipBoard?.country(e)||'unknown')===S.newsCountry)&&(!S.newsChannel||(window.LumiLeadershipBoard?.channel(e)||'unknown')===S.newsChannel)&&(!S.newsDays||(Date.parse(e.observed_at||e.created_at)>=Date.now()-Number(S.newsDays)*86400000)));}
