  function parseSpecs(value){const specs={};for(const raw of String(value||'').split('\n').filter(x=>x.trim())){const index=raw.indexOf('=');if(index<1)throw new Error('每行规格请写成“字段=值”，例如 电压=220。');const key=raw.slice(0,index).trim(),v=raw.slice(index+1).trim();if(!v)throw new Error('规格“'+key+'”缺少值');if(['__proto__','constructor','prototype'].includes(key))throw new Error('规格字段无效');specs[key]=/^-?\d+(\.\d+)?$/.test(v)?Number(v):v==='true'?true:v==='false'?false:v;}return specs;}
