    if(a==='research-close'){S.newResearch=false;return;}
    if(a==='research-country-add'){requirePermission('customer');const draft=drafts['bh-customer-research']||{},country=String(draft.company_country_other||'').trim(),selected=arr(draft.company_countries);if(!country||country.length>100)throw new Error('请填写不超过100字的国家/地区名称。');if(!selected.some(c=>c.toLocaleLowerCase()===country.toLocaleLowerCase())){if(selected.length>=30)throw new Error('最多选择30个国家/地区。');selected.push(country);}drafts['bh-customer-research']={...draft,company_countries:selected,company_country_other:''};return;}
    if(a==='new-customer'){S.newResearch=false;S.crawlAutoStart=null;requirePermission('customer');S.customerId='';S.personEdit='';S.relationEdit='';S.channelEdit='';S.linkedinSearch=null;S.detail=null;S.customerFocus=null;S.answer=null;S.tab='overview';drafts={};return;}
    if(a==='channel-edit'||a==='channel-new'){requirePermission('channel');if(a==='channel-edit'&&!arr(customer()?.channels)[Number(id)])throw new Error('渠道已变化，请刷新后重试');S.channelEdit=a==='channel-edit'?id:'';delete drafts['bh-channel'];return;}
    if(a==='channel-delete'){requirePermission('channel');const channels=[...arr(customer()?.channels)],i=Number(id);if(!Number.isInteger(i)||!channels[i])throw new Error('渠道已变化，请刷新后重试');channels.splice(i,1);await customerPost('',{channels});S.channelEdit='';delete drafts['bh-channel'];ctx.toast('已移除该渠道');return;}
    if(a==='subscription-toggle'){requirePermission('subscription');const subscription=arr(S.detail.subscriptions).find(s=>s.id===id);if(!subscription)throw new Error('订阅已变化，请刷新后重试');await customerPost('subscriptions',{id,enabled:!subscription.enabled});return;}
    if(a==='subscription-run'){requirePermission('subscription');await customerPost('subscriptions/'+id+'/run',{});return;}
